// Типы клиентов по уровням (id персонажа 1..14)
// Какие гости приходят на уровне — по таблице exe (Project_ru.met, таблица 0x98: «новый гость на уровне N», N — номер уровня бара 1..35).
// Раньше было по данным Flash (гости 12/6/10/5/14 приходили на 1–3 уровня позже, чем в exe). 1, 9, 13 — стартовый набор; №7 (без озвучки) не приходит.
const GUEST_BASE = [1, 3, 9, 13];
const GUEST_INTRO = { 2: 2, 6: 8, 9: 12, 13: 6, 16: 10, 20: 5, 23: 14, 27: 4, 30: 11 };   // уровень → новый гость
function guestPool(n) {
  const pool = GUEST_BASE.slice();
  for (const lv of Object.keys(GUEST_INTRO)) if (n >= +lv) pool.push(GUEST_INTRO[lv]);
  return pool;
}

// Веса появления гостей по локации (exe: таблицы 0x99..0x9d, по 18 значений; индекс = номер гостя − 1). Нулевой вес — гость в этой локации не приходит.
// Выбор: взвешенный случайный среди открытых к этому уровню (GUEST_INTRO) и ещё не сидящих в баре — как в обработчике события «пришёл гость» (FUN_0045b6b0).
const GUEST_WEIGHTS = [[33,33,33,0,0,0,0,33,33,0,0,0,33,0,0,0,0,0],[6,7,10,0,0,33,0,33,10,0,0,33,20,0,0,0,0,0],[13,19,0,0,33,0,0,10,15,33,0,5,0,0,0,0,0,0],[0,8,0,33,9,15,0,0,11,0,0,10,0,33,0,0,0,0],[0,29,0,0,27,4,0,0,0,18,33,0,0,18,0,0,0,33]];
function pickGuest(candidates, loc) {
  const w = GUEST_WEIGHTS[Math.min(GUEST_WEIGHTS.length, Math.max(1, loc)) - 1];
  let total = 0; const ws = candidates.map((id) => { const x = Math.max(0, w[id - 1] || 0); total += x; return x; });
  if (total <= 0) return candidates[Math.floor(Math.random() * candidates.length)];
  let r = Math.random() * total;
  for (let i = 0; i < candidates.length; i++) { r -= ws[i]; if (r < 0) return candidates[i]; }
  return candidates[candidates.length - 1];
}

